// Asserts that two uint8_t arrays representing numbers (digits) are equal up to a given length.
void helper_assert_number_array_equal(uint8_t *actual, uint8_t *expected, int length) {
    for (int i = 0; i < length; i++) {
        TEST_ASSERT_EQUAL_INT(expected[i], actual[i]);
    }
}

// Captures stdout output of print_number and asserts it matches expected string.
void helper_assert_print_number_output(uint8_t *number, uint8_t N, int8_t num_digits_to_print, const char *expected_output) {
    int *cap = capture_stdout_start();
    print_number(number, N, num_digits_to_print);
    assert_stdout_equals(cap, expected_output);
}

// ========== Searched From Pool - Utility Operations ==========

// Function: capture_stdout_start (from helper pool)
int *capture_stdout_start(void) {
    stdout_capture_t *cap = malloc(sizeof(stdout_capture_t));
    if (!cap) return NULL;
    cap->buffer = NULL;
    cap->buffer_size = 0;
    /* Create a pipe */
    int pipefd[2];
    if (pipe(pipefd) == -1) {
        free(cap);
        return NULL;
    }
    cap->pipe_read_fd = pipefd[0];
    cap->pipe_write_fd = pipefd[1];
    /* Save original stdout */
    cap->saved_stdout_fd = dup(STDOUT_FILENO);
    if (cap->saved_stdout_fd == -1) {
        close(cap->pipe_read_fd);
        close(cap->pipe_write_fd);
        free(cap);
        return NULL;
    }
    /* Redirect stdout to the pipe write end */
    if (dup2(cap->pipe_write_fd, STDOUT_FILENO) == -1) {
        close(cap->saved_stdout_fd);
        close(cap->pipe_read_fd);
        close(cap->pipe_write_fd);
        free(cap);
        return NULL;
    }
    return (int *)cap;
}

// Function: capture_stdout_stop (from helper pool)
char *capture_stdout_stop(int *cap) {
    stdout_capture_t *capture = (stdout_capture_t *)cap;
    if (!capture) return NULL;
    /* Flush stdout to ensure all output is written to pipe */
    fflush(stdout);
    /* Close write end of pipe to signal EOF */
    close(capture->pipe_write_fd);
    /* Restore original stdout */
    dup2(capture->saved_stdout_fd, STDOUT_FILENO);
    close(capture->saved_stdout_fd);
    /* Read captured output from pipe */
    size_t total_read = 0;
    size_t buffer_capacity = 1024;
    char *buffer = malloc(buffer_capacity);
    if (!buffer) {
        close(capture->pipe_read_fd);
        free(capture);
        return NULL;
    }
    ssize_t bytes_read;
    while ((bytes_read = read(capture->pipe_read_fd, buffer + total_read,
                               buffer_capacity - total_read - 1)) > 0) {
        total_read += bytes_read;
        if (total_read >= buffer_capacity - 1) {
            buffer_capacity *= 2;
            char *new_buffer = realloc(buffer, buffer_capacity);
            if (!new_buffer) {
                free(buffer);
                close(capture->pipe_read_fd);
                free(capture);
                return NULL;
            }
            buffer = new_buffer;
        }
    }
    buffer[total_read] = '\0';
    close(capture->pipe_read_fd);
    free(capture);
    return buffer;
}

