// Creates a temporary text file with given lines of numbers for testing get_number.
char *helper_create_test_file(const char **lines, int num_lines) {
    char *filename = malloc(20 * sizeof(char));
    if (!filename) return NULL;
    srand(time(NULL));
    snprintf(filename, 20, "num_%d_%d.txt", (int)getpid(), rand());
    FILE *fp = fopen(filename, "w");
    if (!fp) {
        free(filename);
        return NULL;
    }
    for (int i = 0; i < num_lines; i++) {
        fprintf(fp, "%s
", lines[i]);
    }
    fclose(fp);
    return filename;
}

// Deletes a temporary test file created by helper_create_test_file.
void helper_cleanup_test_file(char *filename) {
    if (filename) {
        remove(filename);
        free(filename);
    }
}

